package com.ruoyi.medical.persistence;
import com.ruoyi.medical.contracts.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Actual shared EvaluationService path; only DB and pre-existing grants are named fixture boundaries. */
class FormalEvaluationMetadataBoundaryTest {
 @Test void preparationMetadataCarriesNoResultOrScoresAndCreatesNoAcceptanceProof()throws Exception{try(var f=new ExpertFixture()){var e=new ExpertEvaluationFixture(f);f.transaction(()->{var m=e.service.requireFormalDefinitionMetadata(f.f.admission,e.definition.evaluation_id());assertEquals(e.hash,m.row().contentHash());assertEquals(e.definition.evaluation_id(),m.definition().evaluation_id());assertFalse(java.util.Arrays.stream(m.row().getClass().getRecordComponents()).anyMatch(c->c.getName().toLowerCase().contains("result")||c.getName().toLowerCase().contains("score")));verifyNoInteractions(e.refs);assertThrows(TenantAccessException.class,()->e.service.requireFormalAcceptance(f.f.admission,e.definition.evaluation_id(),null));return null;});}}
 @Test void metadataRecheckRejectsChangedRevision()throws Exception{try(var f=new ExpertFixture()){var e=new ExpertEvaluationFixture(f);f.transaction(()->{var m=e.service.requireFormalDefinitionMetadata(f.f.admission,e.definition.evaluation_id());e.revision=e.revision.add(java.math.BigInteger.ONE);assertThrows(TenantAccessException.class,m::requireUnchanged);return null;});}}
 @Test void metadataDoesNotEscapeOriginalTransactionScope()throws Exception{try(var f=new ExpertFixture()){var e=new ExpertEvaluationFixture(f);var m=f.transaction(()->e.service.requireFormalDefinitionMetadata(f.f.admission,e.definition.evaluation_id()));f.transaction(()->{assertThrows(TenantAccessException.class,m::requireUnchanged);return null;});}}
 @Test void missingCurrentEvaluationReadDeniesMetadata()throws Exception{try(var f=new ExpertFixture()){var e=new ExpertEvaluationFixture(f);f.f.allowed.set(false);f.transaction(()->{assertThrows(TenantAccessException.class,()->e.service.requireFormalDefinitionMetadata(f.f.admission,e.definition.evaluation_id()));return null;});}}
}
